-- ============================================================
-- league_data.sql — 联赛真实数据（由 scripts_cloudbase/fetch-leagues.py 生成）
-- 生成时间：2026-10-08T22:58:36+08:00
-- 数据源：英超/欧冠 = premierleague.com 官方数据接口（26-27 赛季）
--         CBA      = cbaleague.com 官网 portal-server（26-27 赛程）
-- 可重复执行：先按联赛清空 league_* 三表与 matches，再插入
-- ============================================================

BEGIN;

-- ---------- 0. 约束对齐：league_players 名次允许并列（Day 21 零拍板）----------
-- 原约束 UNIQUE (league_id, board, rank) 会把真实射手榜的并列名次直接拒掉
-- （英超前 10 里 8 人并列第 3）。放宽为四列，仍防「同榜同名次挂同一球员两次」。
ALTER TABLE public.league_players DROP CONSTRAINT IF EXISTS league_players_rank_uniq;
ALTER TABLE public.league_players ADD CONSTRAINT league_players_rank_uniq
  UNIQUE (league_id, board, rank, player_name);

-- ---------- 1. 联赛维度表 ----------
VALUES ('epl', '英超', 'football', '⚽', '英格兰足球超级联赛 · 2026/27 赛季', '["schedule", "standings", "race", "scorers", "players"]', '2026-10-08T22:58:36+08:00')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;
VALUES ('ucl', '欧冠', 'football', '🏆', '欧洲冠军联赛 · 2026/27 赛季（联赛阶段）', '["schedule", "standings", "knockout", "bracket", "players"]', '2026-10-08T22:58:36+08:00')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;
VALUES ('cba', 'CBA', 'basketball', '🏀', '中国男子篮球职业联赛 · 2026/27 赛季', '["schedule", "standings", "players"]', '2026-10-08T22:58:36+08:00')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;

-- ---------- 2. 清空旧的联赛数据 ----------
DELETE FROM public.league_schedule WHERE league_id IN ('epl', 'ucl', 'cba');
DELETE FROM public.league_standings WHERE league_id IN ('epl', 'ucl', 'cba');
DELETE FROM public.league_players WHERE league_id IN ('epl', 'ucl', 'cba');
DELETE FROM public.matches WHERE league IN ('英超', '欧冠', 'CBA');

-- ---------- 3. league_standings（英超 20 队 / 欧冠 36 队）----------

-- ---------- 4. league_players（射手榜 board=scorers）----------

-- ---------- 5. league_schedule ----------

-- ---------- 6. matches（赛程比分页，跨联赛）----------

COMMIT;

-- 收尾自检
SELECT l.id, l.name, l.sport,
       (SELECT count(*) FROM public.league_schedule  s WHERE s.league_id = l.id) AS 赛程,
       (SELECT count(*) FROM public.league_standings t WHERE t.league_id = l.id) AS 积分榜,
       (SELECT count(*) FROM public.league_players   p WHERE p.league_id = l.id) AS 球员
FROM   public.leagues l WHERE l.id IN ('epl','ucl','cba') ORDER BY l.id;
SELECT league, count(*) AS 综合赛程 FROM public.matches WHERE league IN ('英超','欧冠','CBA') GROUP BY league ORDER BY league;
